use crate::llm::client::{LlmClient, LlmError, LlmResult};
use crate::llm::prompts::SYSTEM_PROMPT;
use crate::llm::repair::repair_action;
use crate::llm::schema::ActionSchema;
use crate::telemetry;
use crate::types::{Action, Observation};
use async_trait::async_trait;
use reqwest::Client;
use serde::Deserialize;
use serde_json::{json, Value};
use std::time::{Duration, Instant};
use tracing::Instrument;

#[derive(Clone, Debug)]
pub struct OpenAiConfig {
    pub api_key: String,
    pub base_url: String,
    pub model: String,
    pub timeout: Duration,
    pub temperature: f32,
    pub max_tokens: Option<u32>,
}

impl OpenAiConfig {
    pub fn endpoint(&self) -> String {
        format!(
            "{}/chat/completions",
            self.base_url.trim_end_matches('/')
        )
    }
}

pub struct OpenAiClient {
    http: Client,
    config: OpenAiConfig,
    schema: ActionSchema,
}

impl OpenAiClient {
    pub fn new(config: OpenAiConfig) -> LlmResult<Self> {
        if config.api_key.trim().is_empty() {
            return Err(LlmError::new("missing_api_key", "api key is required"));
        }
        let http = Client::builder()
            .timeout(config.timeout)
            .build()
            .map_err(|err| LlmError::new("client_error", err.to_string()))?;
        Ok(Self {
            http,
            config,
            schema: ActionSchema::default(),
        })
    }

    fn build_prompt(
        &self,
        task: &str,
        plan: Option<&str>,
        observation: &Observation,
        observations: &std::collections::VecDeque<Observation>,
        history: &[Action],
    ) -> LlmResult<String> {
        let observation_json = serde_json::to_string(observation)
            .map_err(|err| LlmError::new("serialize_error", err.to_string()))?;
        let observations_json = serde_json::to_string(observations)
            .map_err(|err| LlmError::new("serialize_error", err.to_string()))?;
        let history_json = serde_json::to_string(history)
            .map_err(|err| LlmError::new("serialize_error", err.to_string()))?;
        let schema_json = serde_json::to_string(self.schema.json())
            .map_err(|err| LlmError::new("serialize_error", err.to_string()))?;
        let plan_text = plan.unwrap_or("(none)");

        Ok(format!(
            "Task: {task}\nPlan: {plan_text}\nObservation: {observation_json}\nRecentObservations: {observations_json}\nHistory: {history_json}\nSchema: {schema_json}\nReturn exactly one JSON action object matching the schema and nothing else.",
        ))
    }

    fn parse_content(&self, content: &str) -> LlmResult<Action> {
        let value = match self.parse_json_value(content) {
            Ok(value) => value,
            Err(err) => return self.attempt_repair(err, content),
        };

        if let Err(err) = self.reject_multi_action(&value) {
            return self.attempt_repair(err, content);
        }

        match self.parse_value_strict(value.clone()) {
            Ok(action) => Ok(action),
            Err(err) => self.attempt_repair(err, content),
        }
    }

    #[allow(dead_code)]
    fn parse_strict(&self, content: &str) -> LlmResult<Action> {
        let value = self.parse_json_value(content)?;
        self.parse_value_strict(value)
    }

    fn parse_json_value(&self, content: &str) -> LlmResult<Value> {
        let trimmed = content.trim();
        if trimmed.is_empty() {
            return Err(LlmError::new("invalid_json", "empty response"));
        }
        serde_json::from_str(trimmed).map_err(|err| LlmError::new("invalid_json", err.to_string()))
    }

    fn parse_value_strict(&self, value: Value) -> LlmResult<Action> {
        self.schema
            .validate_json(&value)
            .map_err(|errors| {
                let message = errors
                    .into_iter()
                    .map(|err| err.message)
                    .collect::<Vec<_>>()
                    .join("; ");
                LlmError::new("schema_violation", message)
            })?;
        serde_json::from_value(value)
            .map_err(|err| LlmError::new("deserialize_error", err.to_string()))
    }

    fn reject_multi_action(&self, value: &Value) -> LlmResult<()> {
        match value {
            Value::Array(_) => Err(LlmError::new(
                "multi_action",
                "expected single JSON action object, got array",
            )),
            Value::Object(map) => {
                if matches!(map.get("action"), Some(Value::Array(_)))
                    || matches!(map.get("actions"), Some(Value::Array(_)))
                {
                    Err(LlmError::new(
                        "multi_action",
                        "expected single JSON action object, got action array",
                    ))
                } else {
                    Ok(())
                }
            }
            _ => Ok(()),
        }
    }

    fn attempt_repair(&self, err: LlmError, content: &str) -> LlmResult<Action> {
        telemetry::inc_repair_attempt();
        match repair_action(content, &self.schema) {
            Ok(action) => {
                telemetry::inc_repair_success();
                tracing::info!(
                    event = "repair_success",
                    error_code = err.code,
                    repaired = true
                );
                Ok(action)
            }
            Err(repair_err) => {
                let message = format!("{}; repair_failed: {}", err.message, repair_err);
                tracing::warn!(
                    event = "repair_failed",
                    error_code = err.code,
                    repair_error = %repair_err
                );
                Err(LlmError::new(err.code, message))
            }
        }
    }
}

#[async_trait]
impl LlmClient for OpenAiClient {
    async fn propose_action(
        &self,
        task: &str,
        plan: Option<&str>,
        observation: &Observation,
        observations: &std::collections::VecDeque<Observation>,
        history: &[Action],
    ) -> LlmResult<Action> {
        telemetry::inc_llm_call();
        let start = Instant::now();
        let span = tracing::info_span!("llm_call", model = %self.config.model);
        let result = async {
            let prompt = self.build_prompt(task, plan, observation, observations, history)?;
            let mut body = json!({
                "model": self.config.model,
                "messages": [
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": prompt}
                ],
                "temperature": self.config.temperature
            });
            if let Some(max_tokens) = self.config.max_tokens {
                // OpenAI chat completions now prefer max_completion_tokens.
                body["max_completion_tokens"] = json!(max_tokens);
            }

            let response = self
                .http
                .post(self.config.endpoint())
                .bearer_auth(&self.config.api_key)
                .json(&body)
                .send()
                .await
                .map_err(map_reqwest_error)?;

            if !response.status().is_success() {
                let status = response.status();
                let text = response
                    .text()
                    .await
                    .unwrap_or_else(|_| "<no body>".to_string());
                return Err(LlmError::new(
                    "http_error",
                    format!("status {status}: {text}"),
                ));
            }

            let payload: ChatResponse = response
                .json()
                .await
                .map_err(map_reqwest_error)?;
            let content = payload
                .choices
                .get(0)
                .and_then(|choice| choice.message.content.as_ref())
                .ok_or_else(|| LlmError::new("empty_response", "missing content"))?;
            let content_text = extract_content(content)?;
            self.parse_content(&content_text)
        }
        .instrument(span)
        .await;

        telemetry::record_llm_duration(start.elapsed());
        if let Err(err) = &result {
            telemetry::inc_llm_failure(err.code);
            tracing::warn!(
                event = "llm_failure",
                error_code = err.code,
                error_message_len = err.message.chars().count()

        report_path: report_path.display().to_string(),
        max_steps_per_task,
        required_passes,
        base_url: base_url.clone(),
    })?;

    let actions_dir = actions_work_dir(&report_path);
    let mut results = Vec::with_capacity(tasks.len());

    for task in tasks {
        let started_at = std::time::Instant::now();
        let mut task_config = base_config.clone();
        let step_limit = bench_task_limit(&task, max_steps_per_task);
        task_config.agent.max_steps = step_limit;
        task_config.browser.initial_url = join_base_url(&base_url, &task.start_path);
        task_config.llm.mode = LlmMode::Scripted;

        let actions_json = render_actions(&task.actions, &base_url)
            .map_err(|err| format!("task {} actions: {err}", task.id))?;
        let actions_file = actions_file_path(&actions_dir, &task.id);
        write_actions_file(&actions_file, &actions_json)
            .map_err(|err| format!("task {} actions file: {err}", task.id))?;
        task_config.llm.actions_file = Some(actions_file);

        let run = execute_agent(&task.task, task.plan.as_deref(), &task_config).await;
        let elapsed = started_at.elapsed().as_millis() as u64;
        let task_result = match run {
            Ok(execution) => match execution.result {
                Ok(result) => {
                    let observed_status = match result.status {
                        RunStatus::Done => BenchObservedStatus::Done,
                        RunStatus::MaxSteps => BenchObservedStatus::MaxSteps,
                    };
                    let mut evaluated = evaluate_task(
                        &task,
                        observed_status,
                        result.steps.len(),
                        Some(&result.final_observation.url),
                        Some(&result.final_observation.visible_text),
                        step_limit,
                        None,
                    );
                    evaluated.duration_ms = elapsed;
                    evaluated
                }
                Err(err) => {
                    let mut evaluated = evaluate_task(
                        &task,
                        BenchObservedStatus::Error,
                        execution.steps.len(),
                        None,
                        None,
                        step_limit,
                        Some(&err.to_string()),
                    );
                    evaluated.duration_ms = elapsed;
                    evaluated
                }
            },
            Err(err) => {
                let mut evaluated = evaluate_task(
                    &task,
                    BenchObservedStatus::Error,
                    0,
                    None,
                    None,
                    step_limit,
                    Some(&err.to_string()),
                );
                evaluated.duration_ms = elapsed;
                evaluated
            }
        };
        emit_json(&BenchTaskLog::from(&task_result))?;
        results.push(task_result);
        sleep(sleep_between_tasks()).await;
    }

    let summary = build_summary(&results, required_passes);
    let report = BenchReport {
        timestamp: now_timestamp().map_err(|err| format!("bench timestamp: {err}"))?,
        tasks_dir: tasks_dir.display().to_string(),
        report_path: report_path.display().to_string(),
        max_steps_per_task,
        required_passes,
        summary: summary.clone(),
        results,
    };
    write_report(&report_path, &report)
        .map_err(|err| format!("failed to write bench report: {err}"))?;

    emit_json(&BenchSummaryLog {
        r#type: "bench_summary",
        total_tasks: summary.total_tasks,
        passed_tasks: summary.passed_tasks,
        required_passes: summary.required_passes,
        completion_rate: summary.completion_rate,
        median_steps_success: summary.median_steps_success,
        p95_steps_success: summary.p95_steps_success,
        gate_passed: summary.gate_passed,
        failure_buckets: failure_buckets(&report.results),
        report_path: report_path.display().to_string(),
    })?;

    server.shutdown().await;

    if !summary.gate_passed {
        return Err(format!(
            "benchmark gate failed: passed {} of {} tasks (required {})",
            summary.passed_tasks, summary.total_tasks, summary.required_passes
        )
        .into());
    }

    Ok(())
}

fn resolve_config_path(cli_path: Option<&Path>) -> Option<PathBuf> {
    if let Some(path) = cli_path {
        return Some(path.to_path_buf());
    }
    if let Ok(path) = std::env::var("MBUS_CONFIG") {
        return Some(PathBuf::from(path));
    }
    if let Ok(cwd) = std::env::current_dir() {
        let local = cwd.join("mbus.toml");
        if local.is_file() {
            return Some(local);
        }
    }
    if let Ok(home) = std::env::var("HOME") {
        let home_config = PathBuf::from(home).join(".mbus.toml");
        if home_config.is_file() {
            return Some(home_config);
        }
    }
    None
}

fn resolve_required_text(
    label: &str,
    inline: Option<&str>,
    file_path: Option<&Path>,
) -> Result<String, Box<dyn Error>> {
    match (inline, file_path) {
        (Some(_), Some(_)) => {
            Err(format!("{label}: use only one of --{label} or --{label}-file").into())
        }
        (Some(value), None) => Ok(value.to_string()),
        (None, Some(path)) => {
            let content = std::fs::read_to_string(path)?;
            Ok(content.trim().to_string())
        }
        (None, None) => Err(format!("{label} is required").into()),
    }
}

fn resolve_optional_text(
    label: &str,
    inline: Option<&str>,
    file_path: Option<&Path>,
) -> Result<Option<String>, Box<dyn Error>> {
    match (inline, file_path) {
        (Some(_), Some(_)) => {
            Err(format!("{label}: use only one of --{label} or --{label}-file").into())
        }
        (Some(value), None) => Ok(Some(value.to_string())),
        (None, Some(path)) => {
            let content = std::fs::read_to_string(path)?;
            Ok(Some(content.trim().to_string()))
        }
        (None, None) => Ok(None),
    }
}

